/** Public entry point — the only module consumers/docs should import from. */

export { DataGridContextMenu, type DataGridContextMenuProps } from "./context-menu";
export { DataGridHeaderDropdown, type DataGridHeaderDropdownProps } from "./header-dropdown";
export type {
  CellMenuItemsCtx,
  CellMenuItemsResolver,
  GridMenuItemSpec,
  HeaderMenuItemsCtx,
  HeaderMenuItemsResolver,
} from "./menu-items";

"use client";

import { useCallback, useRef, useState, type MouseEvent as ReactMouseEvent, type ReactNode } from "react";
import type { ContextMenu as ContextMenuPrimitive } from "@base-ui/react/context-menu";
import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuTrigger,
} from "@/components/ui/context-menu";
import { useDataGridActions, useDataGridSelection } from "@/registry/default/components/data-grid/data-grid";
import { useDataGridStoreApi } from "@/registry/default/components/data-grid/data-grid-sdk";
import { resolveContextMenuTarget, type ContextMenuTarget } from "./resolve-context-menu-target";
import { isCellInSelection } from "./selection-queries";
import {
  DataGridHeaderMenuItemsContext,
  renderContextMenuItems,
  useDefaultCellMenuItems,
  useDefaultHeaderMenuItems,
  type CellMenuItemsResolver,
  type HeaderMenuItemsResolver,
} from "./menu-items";
import { useHasCreateRow, useHasDuplicateRow } from "./has-row-op";

/** Props for {@link DataGridContextMenu}. */
export type DataGridContextMenuProps = {
  className?: string;
  children?: ReactNode;
  /**
   * Resolves the cell-surface item set (Cut/Copy/Paste, Clear contents, Insert row above/below,
   * Duplicate row(s), Delete row(s)). `defaults` is the built-in set as
   * {@link GridMenuItemSpec} entries for the current state; return `defaults` unchanged, a
   * filtered/reordered/extended array, or a fully custom set. The returned array is the complete
   * item set — it owns the items, their order, and their gating. Runs during the wrapper's render
   * (a plain function call, not a component), so it must not call hooks. Omit for the built-in
   * set.
   */
  getCellMenuItems?: CellMenuItemsResolver;
  /**
   * Resolves the header-surface item set (Sort asc/desc/clear, Pin left/right/unpin, Hide column,
   * Autosize column). `defaults` is the built-in set as {@link GridMenuItemSpec} entries for the
   * current state; the return value is the complete item set. Applies to the right-click header
   * menu AND every `DataGridHeaderDropdown` rendered inside this wrapper (it flows through
   * {@link DataGridHeaderMenuItemsContext}). Runs during the wrapper's render, so it must not
   * call hooks. Omit for the built-in set.
   */
  getHeaderMenuItems?: HeaderMenuItemsResolver;
};

/**
 * Wraps `children` (the grid) with the shadcn `ContextMenu`. On `contextmenu`, inspects the event
 * target to decide the surface (cell vs. header) and, for a cell outside
 * the current selection, selects that cell first (Excel behavior) before the menu opens.
 *
 * A surface that resolves to neither (row markers, empty grid space below the last row, the
 * scrollbar gutter, ...) has no menu content to show — `resolveContextMenuTarget` already returns
 * `null` there. Left alone, Base UI's `ContextMenuRoot` still opens the (then childless) popup on
 * that right-click, rendering a visibly empty rounded-card sliver.
 * `onOpenChange` here cancels that open via `eventDetails.cancel()` — checked against `targetRef`
 * (synchronous, unlike `target` state) since the "should this open" decision has to be made in the
 * same tick as the triggering event, before React re-renders. The native browser context menu is
 * deliberately NOT re-enabled for this case (no `event.preventDefault()` is skipped) — suppressing
 * silently, matching how a plain click on empty grid space is already a quiet no-op elsewhere, is
 * less surprising than a browser chrome menu popping up only sometimes depending on grid surface.
 */
export function DataGridContextMenu(props: DataGridContextMenuProps): ReactNode {
  const { className, children, getCellMenuItems, getHeaderMenuItems } = props;
  const actions = useDataGridActions();
  const selection = useDataGridSelection();
  const storeApi = useDataGridStoreApi();
  const canInsertRow = useHasCreateRow();
  const canDuplicateRow = useHasDuplicateRow();
  const selectionRef = useRef(selection);
  selectionRef.current = selection;
  const [target, setTarget] = useState<(ContextMenuTarget & { rowId?: string }) | null>(null);
  const targetRef = useRef<(ContextMenuTarget & { rowId?: string }) | null>(null);
  // Lives here (not in the menu content) because the content portals and unmounts on close —
  // a permission-denied paste result must survive the close/reopen cycle to keep showing the
  // "use Ctrl+V" hint on the next open.
  const [pasteBlocked, setPasteBlocked] = useState(false);

  // Captured at contextmenu time (not via useDataGridContainer): ContextMenuContent portals to
  // document.body, outside DataGridRoot's subtree, so its children can't reach the root context.
  const scrollRootRef = useRef<HTMLElement | null>(null);

  const onContextMenu = useCallback(
    (event: ReactMouseEvent<HTMLDivElement>) => {
      const resolved = resolveContextMenuTarget(event.target);
      // the DOM carries only view-space coords; the stable row id comes off the store at event time.
      let next: (ContextMenuTarget & { rowId?: string }) | null = resolved;
      if (resolved?.kind === "cell") {
        const s = storeApi.getState();
        const dataRowIndex = s.viewIndex[resolved.row];
        if (dataRowIndex !== undefined) {
          const dataRow = s.data[dataRowIndex];
          if (dataRow !== undefined) next = { ...resolved, rowId: s.getRowId(dataRow, dataRowIndex) };
        }
      }
      targetRef.current = next;
      setTarget(next);
      scrollRootRef.current = event.target instanceof Element ? event.target.closest('[role="grid"]') : null;
      if (resolved?.kind === "cell" && !isCellInSelection(selectionRef.current, { row: resolved.row, col: resolved.col })) {
        actions.selectCellAt({ row: resolved.row, col: resolved.col });
      }
    },
    [actions, storeApi],
  );

  const onOpenChange = useCallback((open: boolean, eventDetails: ContextMenuPrimitive.Root.ChangeEventDetails) => {
    if (open && targetRef.current === null) eventDetails.cancel();
  }, []);

  // The built-in sets as specs, resolved for the current state. Computed even with no menu open
  // (hook rules); a resolver receives them as `defaults`, and without a resolver they render as-is.
  const defaultCellSpecs = useDefaultCellMenuItems({
    row: target?.kind === "cell" ? target.row : 0,
    canInsertRow,
    canDuplicateRow,
    pasteBlocked,
    onPasteBlocked: () => setPasteBlocked(true),
  });
  const defaultHeaderSpecs = useDefaultHeaderMenuItems({
    columnId: target?.kind === "header" ? target.columnId : "",
    scrollRoot: scrollRootRef.current,
  });

  return (
    <DataGridHeaderMenuItemsContext.Provider value={getHeaderMenuItems ?? null}>
      <ContextMenu onOpenChange={onOpenChange}>
        <ContextMenuTrigger className={className} onContextMenu={onContextMenu}>
          {children}
        </ContextMenuTrigger>
        <ContextMenuContent data-grid-context-menu="">
          {target?.kind === "cell" &&
            renderContextMenuItems(
              getCellMenuItems
                ? getCellMenuItems({ rowId: target.rowId!, viewRowIndex: target.row, columnId: target.columnId, canInsertRow, canDuplicateRow }, defaultCellSpecs)
                : defaultCellSpecs,
            )}
          {target?.kind === "header" &&
            renderContextMenuItems(
              getHeaderMenuItems
                ? getHeaderMenuItems({ columnId: target.columnId, scrollRoot: scrollRootRef.current }, defaultHeaderSpecs)
                : defaultHeaderSpecs,
            )}
        </ContextMenuContent>
      </ContextMenu>
    </DataGridHeaderMenuItemsContext.Provider>
  );
}

"use client";

import { useContext, type ReactElement, type ReactNode } from "react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import type { AnyColumnDef } from "@/registry/default/components/data-grid/data-grid";
import { useDataGridContainer } from "@/registry/default/components/data-grid/data-grid-sdk";
import {
  DataGridHeaderMenuItemsContext,
  renderDropdownMenuItems,
  useDefaultHeaderMenuItems,
  type HeaderMenuItemsResolver,
} from "./menu-items";

/** Props for {@link DataGridHeaderDropdown} — matches the core's `renderHeaderMenu` render-prop ctx exactly. */
export type DataGridHeaderDropdownProps = {
  column: AnyColumnDef;
  index: number;
  /** The core's own ghost-chevron trigger element (styling/aria-label owned by `header-cell.tsx`). */
  trigger: ReactElement;
  /**
   * Resolves this dropdown's item set the same way `DataGridContextMenu`'s `getHeaderMenuItems`
   * does. When the dropdown renders inside a `DataGridContextMenu` wrapper, the wrapper's
   * resolver applies automatically; this prop overrides it for this dropdown only.
   */
  getHeaderMenuItems?: HeaderMenuItemsResolver;
};

/**
 * The primary per-column pin/sort surface: a `DropdownMenu` wrapping the core's chevron trigger,
 * whose content resolves through the same header-item spec list as the header right-click context
 * menu. Wire via `<DataGridRoot renderHeaderMenu={(ctx) => <DataGridHeaderDropdown {...ctx} />}>`.
 */
export function DataGridHeaderDropdown(props: DataGridHeaderDropdownProps): ReactNode {
  const { column, trigger, getHeaderMenuItems } = props;
  // rendered inline inside DataGridRoot's subtree (not portaled like the context menu), so the
  // container is reachable directly via the shared hook instead of a contextmenu-time ref capture.
  const scrollRoot = useDataGridContainer();
  const inheritedResolver = useContext(DataGridHeaderMenuItemsContext);
  const defaultSpecs = useDefaultHeaderMenuItems({ columnId: column.id, scrollRoot: scrollRoot.current });
  const resolver = getHeaderMenuItems ?? inheritedResolver;
  const specs = resolver
    ? resolver({ columnId: column.id, scrollRoot: scrollRoot.current }, defaultSpecs)
    : defaultSpecs;

  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={trigger} />
      {/* data-grid-header-menu-popup marks this a portal (React-tree-only bubble target) so
          header-cell.tsx's own pointerdown/click handlers can ignore events that originate here
          (its label press otherwise reassigns e.g. a "Hide column" click into a column-select). */}
      <DropdownMenuContent data-grid-header-dropdown="" data-grid-header-menu-popup="" align="end">
        {renderDropdownMenuItems(specs)}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import type { AnyColumnDef } from "@/registry/default/components/data-grid/data-grid";
import { measureColumnAutosizeWidth } from "@/registry/default/components/data-grid/data-grid-sdk";

const ABSOLUTE_MIN_WIDTH = 32;

/** Reads the rendered text of every currently-mounted gridcell for `columnId`, scoped to `root` — same DOM contract `use-column-resize.ts`'s double-click autosize reads (`role="gridcell"` + `data-column-id`). */
function readRenderedCellTexts(root: Element | null, columnId: string): string[] {
  if (!root) return [];
  const cells = root.querySelectorAll(`[role="gridcell"][data-column-id="${CSS.escape(columnId)}"]`);
  return Array.from(cells, (cell) => cell.textContent ?? "");
}

/**
 * Autosizes `column` to fit its header text plus every currently-rendered cell's text, using
 * `root`'s computed font so measurement matches what's on screen. `commitWidth` must be the commit
 * point (`commitColumnWidth`), not the per-frame drag write: autosize is one gesture and fires
 * `onColumnLayoutChange` once.
 */
export function autosizeColumn(
  root: Element | null,
  column: AnyColumnDef,
  commitWidth: (id: string, width: number) => void,
): void {
  const font = root ? getComputedStyle(root).font : "";
  const headerText = column.headerText ?? (typeof column.header === "string" ? column.header : "");
  const cellTexts = readRenderedCellTexts(root, column.id);
  const width = measureColumnAutosizeWidth({
    headerText,
    cellTexts,
    font,
    minWidth: Math.max(ABSOLUTE_MIN_WIDTH, column.minWidth ?? 0),
    maxWidth: column.maxWidth,
  });
  commitWidth(column.id, width);
}

"use client";

import {
  createContext,
  Fragment,
  useCallback,
  type ReactNode,
} from "react";
import {
  ArrowDown,
  ArrowUp,
  Clipboard,
  Copy,
  CopyPlus,
  Eraser,
  EyeOff,
  MoveHorizontal,
  Pin,
  PinOff,
  Plus,
  Scissors,
  Trash2,
  X,
} from "lucide-react";
import { ContextMenuItem, ContextMenuSeparator } from "@/components/ui/context-menu";
import { DropdownMenuItem, DropdownMenuSeparator } from "@/components/ui/dropdown-menu";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import {
  useDataGridActions,
  useDataGridAllColumns,
  useDataGridClipboard,
  useDataGridKeymap,
  useDataGridLabels,
  useDataGridReadOnly,
  useDataGridSelection,
  useDataGridSortState,
  useDataGridColumnFeatureFlags,
} from "@/registry/default/components/data-grid/data-grid";
import { autosizeColumn } from "./autosize-column";
import { MenuShortcut } from "./menu-shortcut";
import { selectedViewRows } from "./selection-queries";

/**
 * One context/dropdown menu entry, in display order. The built-in sets are these specs; a
 * resolver's return value is the complete item set (the consumer owns items, order, and gating).
 */
export type GridMenuItemSpec =
  | {
      /** Stable identity for locating and replacing a built-in item. Built-in ids: `cut`, `copy`, `paste`, `clear-contents`, `insert-row-above`, `insert-row-below`, `duplicate-rows`, `delete-rows` (cell) and `sort-asc`, `sort-desc`, `clear-sort`, `pin-left`, `pin-right`, `unpin`, `hide-column`, `autosize` (header); separators use `sep-*` ids. */
      id: string;
      /** Display label; i18n is the caller's (the built-ins use `labels.contextMenu`). */
      label: string;
      /** Leading icon element (lucide convention: `size-4 text-muted-foreground`). */
      icon?: ReactNode;
      /** Keymap binding rendered as a keycap hint at the item's end. */
      shortcut?: string;
      /** Renders the item inert. With a `tooltip`, it renders aria-disabled (hover still reaches it) so the hint stays reachable. */
      disabled?: boolean;
      /** Destructive (danger-red) item styling. */
      destructive?: boolean;
      /** Hover hint shown while the item is disabled; the built-in Paste uses it for the permission-blocked case. */
      tooltip?: string;
      /** Click handler; omit for a display-only item. */
      onClick?: () => void;
    }
  | {
      /** Stable identity; the built-in separators use ids like `sep-clipboard`. */
      id: string;
      /** Marker for a separator entry (no label, no click). */
      separator: true;
    };

/** The right-clicked cell's context, handed to a cell-menu resolver. */
export type CellMenuItemsCtx = {
  /** The right-clicked row's stable `getRowId()` value. */
  rowId: string;
  /** The right-clicked cell's view row index (the same index the built-in set anchors Insert row at). */
  viewRowIndex: number;
  /** The right-clicked cell's column id. */
  columnId: string;
  /** Whether the grid was given a `createRow` prop — the flag the built-in set gates its Insert items on. */
  canInsertRow: boolean;
  /** Whether the grid was given a `duplicateRow` prop — the flag the built-in set gates its Duplicate item on. */
  canDuplicateRow: boolean;
};

/** The right-clicked header's context, handed to a header-menu resolver. */
export type HeaderMenuItemsCtx = {
  /** The right-clicked column's id. */
  columnId: string;
  /** The grid's scroll-container element (for autosize measurement), or null when the event target has no grid ancestor. */
  scrollRoot: HTMLElement | null;
};

/** Resolves the cell-surface item set. Return `defaults` unchanged, a filtered/reordered/extended array, or a fully custom set. */
export type CellMenuItemsResolver = (ctx: CellMenuItemsCtx, defaults: GridMenuItemSpec[]) => GridMenuItemSpec[];

/** Resolves the header-surface item set (right-click menu and `DataGridHeaderDropdown`). Return `defaults` unchanged, a filtered/reordered/extended array, or a fully custom set. */
export type HeaderMenuItemsResolver = (ctx: HeaderMenuItemsCtx, defaults: GridMenuItemSpec[]) => GridMenuItemSpec[];

/**
 * Carries the `DataGridContextMenu` wrapper's `getHeaderMenuItems` resolver to
 * `DataGridHeaderDropdown`s rendered inside the wrapper's subtree, so one resolver covers both
 * header surfaces. `null` when no wrapper is mounted (the dropdown then uses its own prop).
 */
export const DataGridHeaderMenuItemsContext = createContext<HeaderMenuItemsResolver | null>(null);

/** The built-in cell-surface set as specs, resolved for the current grid state (labels, keymap, selection, clipboard gating). */
export function useDefaultCellMenuItems(args: {
  row: number;
  canInsertRow: boolean;
  canDuplicateRow: boolean;
  pasteBlocked: boolean;
  onPasteBlocked: () => void;
}): GridMenuItemSpec[] {
  const { row, canInsertRow, canDuplicateRow, pasteBlocked, onPasteBlocked } = args;
  const actions = useDataGridActions();
  const selection = useDataGridSelection();
  const clipboard = useDataGridClipboard();
  const readOnly = useDataGridReadOnly();
  const labels = useDataGridLabels();
  const keymap = useDataGridKeymap();

  // Row-op items act on every view row covered by the current selection, falling back to the
  // right-clicked row (same rule as the keyboard/native-clipboard gating).
  const targetRows = selectedViewRows(selection);
  const rows = targetRows.length > 0 ? targetRows : [row];

  const onPaste = useCallback(() => {
    if (pasteBlocked || readOnly) return;
    clipboard.pasteFromClipboard().then((result) => {
      if (result === "permission-denied") onPasteBlocked();
    });
  }, [clipboard, onPasteBlocked, pasteBlocked, readOnly]);

  const specs: GridMenuItemSpec[] = [
    { id: "cut", label: labels.contextMenu.cut, icon: <Scissors className="size-4 text-muted-foreground" />, shortcut: "mod+x", disabled: readOnly, onClick: clipboard.cut },
    { id: "copy", label: labels.contextMenu.copy, icon: <Copy className="size-4 text-muted-foreground" />, shortcut: "mod+c", onClick: clipboard.copy },
    {
      id: "paste",
      label: labels.contextMenu.paste,
      icon: <Clipboard className="size-4 text-muted-foreground" />,
      shortcut: "mod+v",
      disabled: pasteBlocked || readOnly,
      tooltip: pasteBlocked && !readOnly ? labels.contextMenu.pasteBlocked : undefined,
      onClick: onPaste,
    },
    { id: "sep-clipboard", separator: true },
    { id: "clear-contents", label: labels.contextMenu.clearContents, icon: <Eraser className="size-4 text-muted-foreground" />, shortcut: keymap.deleteContents?.[0], disabled: readOnly, onClick: () => actions.deleteSelection() },
    { id: "sep-rows", separator: true },
  ];
  if (canInsertRow) {
    specs.push(
      { id: "insert-row-above", label: labels.contextMenu.insertRowAbove, icon: <Plus className="size-4 text-muted-foreground" />, shortcut: keymap.insertRowAbove?.[0], disabled: readOnly, onClick: () => actions.insertRow(row, "above") },
      { id: "insert-row-below", label: labels.contextMenu.insertRowBelow, icon: <Plus className="size-4 text-muted-foreground" />, shortcut: keymap.insertRowBelow?.[0], disabled: readOnly, onClick: () => actions.insertRow(row, "below") },
    );
  }
  if (canDuplicateRow) {
    specs.push({ id: "duplicate-rows", label: labels.contextMenu.duplicateRows(rows.length), icon: <CopyPlus className="size-4 text-muted-foreground" />, shortcut: keymap.duplicateRow?.[0], disabled: readOnly, onClick: () => actions.duplicateRows(rows) });
  }
  specs.push({ id: "delete-rows", label: labels.contextMenu.deleteRows(rows.length), icon: <Trash2 className="size-4" />, shortcut: keymap.deleteRows?.[0], disabled: readOnly, destructive: true, onClick: () => actions.deleteRows(rows) });
  return specs;
}

/** The built-in header-surface set as specs, resolved for the current grid state (sort, pin/resize flags, labels). */
export function useDefaultHeaderMenuItems(args: { columnId: string; scrollRoot: HTMLElement | null }): GridMenuItemSpec[] {
  const { columnId, scrollRoot } = args;
  const actions = useDataGridActions();
  const sortState = useDataGridSortState();
  const columns = useDataGridAllColumns();
  const { enableColumnPinning, enableColumnResize } = useDataGridColumnFeatureFlags();
  const labels = useDataGridLabels();

  const column = columns.find((c) => c.id === columnId);
  if (!column) return [];

  const sortable = column.sortable !== false;
  const pinnable = enableColumnPinning && column.pinnable !== false;
  // Mirrors the core double-click autosize's gate: with either flag off the action does not
  // exist, so the item is hidden (not disabled) to match the absent resize handle.
  const resizable = enableColumnResize && (column.resizable ?? true);
  const currentSort = sortState.find((s) => s.columnId === columnId)?.direction;

  const specs: GridMenuItemSpec[] = [];
  if (sortable) {
    specs.push(
      { id: "sort-asc", label: labels.contextMenu.sortAsc, icon: <ArrowUp className="size-4 text-muted-foreground" />, onClick: () => actions.setSorts([{ columnId, direction: "asc" }]) },
      { id: "sort-desc", label: labels.contextMenu.sortDesc, icon: <ArrowDown className="size-4 text-muted-foreground" />, onClick: () => actions.setSorts([{ columnId, direction: "desc" }]) },
    );
    if (currentSort) {
      specs.push({ id: "clear-sort", label: labels.contextMenu.clearSort, icon: <X className="size-4 text-muted-foreground" />, onClick: () => actions.setSorts(sortState.filter((s) => s.columnId !== columnId)) });
    }
    specs.push({ id: "sep-sort", separator: true });
  }
  specs.push(
    { id: "pin-left", label: labels.contextMenu.pinLeft, icon: <Pin className="size-4 text-muted-foreground" />, disabled: !pinnable, onClick: () => actions.setColumnPin(columnId, "left") },
    { id: "pin-right", label: labels.contextMenu.pinRight, icon: <Pin className="size-4 text-muted-foreground" />, disabled: !pinnable, onClick: () => actions.setColumnPin(columnId, "right") },
  );
  if (column.pin != null) {
    specs.push({ id: "unpin", label: labels.contextMenu.unpin, icon: <PinOff className="size-4 text-muted-foreground" />, disabled: !pinnable, onClick: () => actions.setColumnPin(columnId, null) });
  }
  specs.push({ id: "hide-column", label: labels.contextMenu.hideColumn, icon: <EyeOff className="size-4 text-muted-foreground" />, onClick: () => actions.setColumnHidden(columnId, true) });
  if (resizable) {
    specs.push(
      { id: "sep-autosize", separator: true },
      { id: "autosize", label: labels.contextMenu.autosize, icon: <MoveHorizontal className="size-4 text-muted-foreground" />, onClick: () => autosizeColumn(scrollRoot, column, actions.commitColumnWidth) },
    );
  }
  return specs;
}

/** One spec entry as a `ContextMenuItem` (or `DropdownMenuItem`) node, with the disabled/tooltip gating the built-ins apply. */
function surfaceItem(
  spec: Exclude<GridMenuItemSpec, { separator: true }>,
  Item: (props: {
    variant?: "default" | "destructive";
    disabled?: boolean;
    "aria-disabled"?: boolean;
    className?: string;
    onClick?: () => void;
    children?: ReactNode;
  }) => ReactNode,
): ReactNode {
  // Not the `disabled` prop when a tooltip is present: it sets `pointer-events-none`, which would
  // also block the tooltip's own hover detection. Visually disabled + click-guarded instead.
  const tooltipDisabled = spec.tooltip != null && spec.disabled;
  const item = (
    <Item
      variant={spec.destructive ? "destructive" : "default"}
      disabled={tooltipDisabled ? undefined : spec.disabled || undefined}
      aria-disabled={tooltipDisabled ? true : undefined}
      className={tooltipDisabled ? "opacity-50" : undefined}
      onClick={spec.disabled ? undefined : spec.onClick}
    >
      {spec.icon}
      {spec.label}
      {spec.shortcut && <MenuShortcut binding={spec.shortcut} />}
    </Item>
  );
  if (!tooltipDisabled) return item;
  return (
    <Tooltip>
      <TooltipTrigger render={item} />
      <TooltipContent>{spec.tooltip}</TooltipContent>
    </Tooltip>
  );
}

/** Renders a spec list as the right-click context menu's item nodes. */
export function renderContextMenuItems(specs: GridMenuItemSpec[]): ReactNode {
  return (
    <Fragment>
      {specs.map((spec) =>
        "separator" in spec ? (
          <ContextMenuSeparator key={spec.id} />
        ) : (
          <Fragment key={spec.id}>{surfaceItem(spec, ContextMenuItem)}</Fragment>
        ),
      )}
    </Fragment>
  );
}

/** Renders a spec list as the header dropdown's item nodes. */
export function renderDropdownMenuItems(specs: GridMenuItemSpec[]): ReactNode {
  return (
    <Fragment>
      {specs.map((spec) =>
        "separator" in spec ? (
          <DropdownMenuSeparator key={spec.id} />
        ) : (
          <Fragment key={spec.id}>{surfaceItem(spec, DropdownMenuItem)}</Fragment>
        ),
      )}
    </Fragment>
  );
}

"use client";

import type { ReactNode } from "react";
import { formatShortcut } from "@/registry/default/components/data-grid/data-grid";
import { Kbd, KbdGroup } from "@/components/ui/kbd";

/** A menu item's shortcut hint as keycaps, pushed to the item's end; renders nothing for an unbound action. */
export function MenuShortcut({ binding }: { binding: string | undefined }): ReactNode {
  if (!binding) return null;
  return (
    <KbdGroup className="ml-auto">
      {formatShortcut(binding).map((token, i) => (
        // tokens within one binding have no other stable identity; index is fine, this list never reorders
        <Kbd key={i}>{token}</Kbd>
      ))}
    </KbdGroup>
  );
}

import { cn } from "@/lib/utils"

/** Keycap treatment, owned by the component (not the prose typography plugin) so docs, the keybindings dialog, and consumer apps render identically. */
const KEYCAP =
  "rounded-sm border bg-muted shadow-[inset_0_-2px_0_0_color-mix(in_oklab,_currentColor_15%,_transparent)]"

function Kbd({ className, ...props }: React.ComponentProps<"kbd">) {
  return (
    <kbd
      data-slot="kbd"
      className={cn(
